<?php
declare(strict_types=1);
require_once __DIR__.'/../config/database.php';
require_once __DIR__.'/includes/auth.php';
date_default_timezone_set('Asia/Manila');
try{$pdo->exec("SET time_zone='+08:00'");}catch(PDOException $e){}
if(!function_exists('fgEscape')){function fgEscape(?string $v):string{return htmlspecialchars($v??'',ENT_QUOTES,'UTF-8');}}
function hLabel(?string $v):string{return ucwords(str_replace(['_','.'],' ',(string)$v));}
function hDate(string $v):bool{if($v==='')return true;$d=DateTimeImmutable::createFromFormat('!Y-m-d',$v);return $d!==false&&$d->format('Y-m-d')===$v;}
function hJson(?string $v):string{if(!$v)return 'No recorded changes.';$d=json_decode($v,true);return is_array($d)?json_encode($d,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE):(string)$v;}
function hUrl(string $tab,int $page,array $f):string{$q=['tab'=>$tab,'page'=>$page];foreach($f as $k=>$v)if($v!=='')$q[$k]=$v;return 'history.php?'.http_build_query($q);}

$tabs=['incidents','notifications','activity'];$tab=(string)($_GET['tab']??'incidents');if(!in_array($tab,$tabs,true))$tab='incidents';
$search=trim((string)($_GET['search']??''));$filter=trim((string)($_GET['filter']??''));$dateFrom=trim((string)($_GET['date_from']??''));$dateTo=trim((string)($_GET['date_to']??''));$filterError='';
if(!hDate($dateFrom)||!hDate($dateTo)||($dateFrom&&$dateTo&&$dateFrom>$dateTo)){$filterError='Please enter a valid date range.';$dateFrom=$dateTo='';}
$config=[
'incidents'=>['Incident History','One row per incident. Open a record to view its complete response timeline.','Response Operations'],
'notifications'=>['Notification History','One row per alert campaign, summarized for any number of residents.','Firebase Delivery'],
'activity'=>['Activity','Review accountable system actions and open a record for full change details.','Security and Accountability']][$tab];

$where=[];$params=[];$dateColumn=$tab==='incidents'?'fi.created_at':($tab==='notifications'?'pn.created_at':'al.created_at');
if($dateFrom){$where[]="$dateColumn>=:df";$params[':df']=$dateFrom.' 00:00:00';}if($dateTo){$where[]="$dateColumn<=:dt";$params[':dt']=$dateTo.' 23:59:59';}
$filterOptions=[];
if($tab==='incidents'){
 $allowed=['awaiting_assignment','assigned','accepted','en_route','on_scene','response_in_progress','resolved','closed','cancelled'];if(!in_array($filter,$allowed,true))$filter='';$filterOptions=$allowed;
 if($filter){$where[]='fi.status=:filter';$params[':filter']=$filter;}if($search){$where[]='(fi.incident_number LIKE :s OR fr.report_number LIKE :s OR fr.location_description LIKE :s)';$params[':s']="%$search%";}
 $from=' FROM flood_incidents fi JOIN flood_reports fr ON fr.id=fi.source_report_id LEFT JOIN incident_status_history ish ON ish.flood_incident_id=fi.id';
 $select='SELECT fi.id,fi.incident_number,fi.priority,fi.status,fi.resolution_summary,fi.created_at,fi.resolved_at,fr.report_number,fr.location_description,COUNT(ish.id) transition_count,MAX(ish.changed_at) last_activity'.$from;
 $group=' GROUP BY fi.id,fi.incident_number,fi.priority,fi.status,fi.resolution_summary,fi.created_at,fi.resolved_at,fr.report_number,fr.location_description';
}elseif($tab==='notifications'){
 $allowed=['normal','warning','critical'];if(!in_array($filter,$allowed,true))$filter='';$filterOptions=$allowed;
 if($filter){$where[]='pn.alert_level=:filter';$params[':filter']=$filter;}if($search){$where[]='(pn.title LIKE :s OR pn.body LIKE :s OR pn.event_type LIKE :s)';$params[':s']="%$search%";}
 $from=' FROM push_notifications pn LEFT JOIN push_notification_recipients pnr ON pnr.push_notification_id=pn.id';
 $select='SELECT pn.id,pn.title,pn.body,pn.alert_level,pn.event_type,pn.created_at,COUNT(pnr.id) targeted,SUM(pnr.delivery_status="sent") sent_count,SUM(pnr.delivery_status="queued") queued_count,SUM(pnr.delivery_status="failed") failed_count,SUM(pnr.delivery_status="skipped") skipped_count,MAX(pnr.sent_at) last_sent_at'.$from;
 $group=' GROUP BY pn.id,pn.title,pn.body,pn.alert_level,pn.event_type,pn.created_at';
}else{
 $filterOptions=$pdo->query('SELECT DISTINCT entity_type FROM audit_logs ORDER BY entity_type')->fetchAll(PDO::FETCH_COLUMN);if($filter&&!in_array($filter,$filterOptions,true))$filter='';
 if($filter){$where[]='al.entity_type=:filter';$params[':filter']=$filter;}if($search){$where[]='(al.action LIKE :s OR al.entity_type LIKE :s OR u.full_name LIKE :s OR u.email LIKE :s)';$params[':s']="%$search%";}
 $from=' FROM audit_logs al LEFT JOIN users u ON u.id=al.actor_user_id';$select='SELECT al.id,al.action,al.entity_type,al.entity_id,al.before_json,al.after_json,al.created_at,u.full_name actor_name,u.email actor_email'.$from;$group='';
}
$whereSql=$where?' WHERE '.implode(' AND ',$where):'';$perPage=12;$page=max(1,(int)($_GET['page']??1));$rows=[];$total=0;$summary=['total'=>0,'success'=>0,'pending'=>0,'attention'=>0];$databaseError='';
try{
 $countSql=$tab==='activity'?'SELECT COUNT(*)'.$from.$whereSql:'SELECT COUNT(*) FROM (SELECT 1'.$from.$whereSql.$group.') history_count';$c=$pdo->prepare($countSql);$c->execute($params);$total=(int)$c->fetchColumn();$pages=max(1,(int)ceil($total/$perPage));$page=min($page,$pages);$offset=($page-1)*$perPage;
 $q=$pdo->prepare($select.$whereSql.$group." ORDER BY $dateColumn DESC LIMIT $perPage OFFSET $offset");$q->execute($params);$rows=$q->fetchAll(PDO::FETCH_ASSOC);
 if($tab==='incidents'){$st=$pdo->query('SELECT COUNT(*) total,SUM(status IN ("resolved","closed")) success,SUM(status NOT IN ("resolved","closed","cancelled")) pending,SUM(status="cancelled") attention FROM flood_incidents')->fetch(PDO::FETCH_ASSOC);foreach($rows as &$r){$t=$pdo->prepare('SELECT ish.from_status,ish.to_status,ish.notes,ish.changed_at,u.full_name actor FROM incident_status_history ish LEFT JOIN users u ON u.id=ish.changed_by WHERE ish.flood_incident_id=:id ORDER BY ish.changed_at,ish.id');$t->execute([':id'=>$r['id']]);$r['timeline']=$t->fetchAll(PDO::FETCH_ASSOC);}unset($r);}
 elseif($tab==='notifications'){$st=$pdo->query('SELECT COUNT(*) total,SUM(x.failed_count=0 AND x.queued_count=0 AND x.targeted>0) success,SUM(x.queued_count>0) pending,SUM(x.failed_count>0 OR x.skipped_count>0) attention FROM (SELECT pn.id,COUNT(pnr.id) targeted,SUM(pnr.delivery_status="queued") queued_count,SUM(pnr.delivery_status="failed") failed_count,SUM(pnr.delivery_status="skipped") skipped_count FROM push_notifications pn LEFT JOIN push_notification_recipients pnr ON pnr.push_notification_id=pn.id GROUP BY pn.id)x')->fetch(PDO::FETCH_ASSOC);}
 else{$st=$pdo->query('SELECT COUNT(*) total,COUNT(DISTINCT actor_user_id) success,SUM(created_at>=DATE_SUB(NOW(),INTERVAL 24 HOUR)) pending,COUNT(DISTINCT entity_type) attention FROM audit_logs')->fetch(PDO::FETCH_ASSOC);}
 foreach($summary as $k=>$_)$summary[$k]=(int)($st[$k]??0);
}catch(PDOException $e){$databaseError='History records could not be loaded.';$pages=1;$offset=0;}
$pageTitle='History';$pageSubtitle='Review monitoring, response, delivery, and accountability records.';$filters=['search'=>$search,'filter'=>$filter,'date_from'=>$dateFrom,'date_to'=>$dateTo];
?>
<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=fgEscape($config[0])?> | FloodGuard</title><link rel="stylesheet" href="../assets/css/admin.css"><link rel="stylesheet" href="../assets/css/sensor-history.css"><link rel="stylesheet" href="../assets/css/history-center.css?v=20260928-2"><link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css"></head><body>
<?php require __DIR__.'/includes/sidebar.php';?><div class="admin-page"><?php require __DIR__.'/includes/topbar.php';?><main class="admin-content standard-admin-page sensor-history-page history-page"><?php $historyActiveTab=$tab;require __DIR__.'/includes/history_tabs.php';?>
