<section class="sensor-statistics history-overview"><?php $cards=$tab==='activity'?[['total','All Activities','bi-journal-text','total'],['success','Active Users','bi-people-fill','normal'],['pending','Last 24 Hours','bi-clock-fill','warning'],['attention','Entity Types','bi-diagram-3-fill','total']]:[['total',$tab==='notifications'?'Notifications':'Incidents','bi-collection-fill','total'],['success',$tab==='notifications'?'Fully Delivered':'Resolved','bi-check-circle-fill','normal'],['pending',$tab==='notifications'?'In Queue':'Active','bi-hourglass-split','warning'],['attention','Needs Attention','bi-exclamation-circle-fill','critical']];foreach($cards as[$k,$l,$i,$cl]):?><article class="sensor-stat-card history-stat"><span class="sensor-stat-icon history-stat-icon <?=fgEscape($cl)?>"><i class="bi <?=fgEscape($i)?>"></i></span><div><span><?=fgEscape($l)?></span><strong><?=number_format($summary[$k])?></strong><small>Recorded in FloodGuard</small></div></article><?php endforeach;?></section>
<section class="content-card sensor-history-card history-panel"><header class="content-card-header sensor-history-header history-panel-header"><div><span class="section-label"><?=fgEscape($config[2])?></span><h2><?=fgEscape($config[0])?></h2><p class="sensor-section-description"><?=fgEscape($config[1])?></p></div><span class="sensor-record-count history-count"><?=number_format($total)?> record<?=$total===1?'':'s'?></span></header>
<form method="get" class="sensor-filters history-filters"><input type="hidden" name="tab" value="<?=fgEscape($tab)?>"><div class="history-filter-search"><i class="bi bi-search"></i><input type="search" name="search" value="<?=fgEscape($search)?>" placeholder="Search history..."></div><select name="filter"><option value=""><?=$tab==='activity'?'All Entities':($tab==='notifications'?'All Alert Levels':'All Statuses')?></option><?php foreach($filterOptions as $o):?><option value="<?=fgEscape((string)$o)?>" <?=$filter===$o?'selected':''?>><?=fgEscape(hLabel((string)$o))?></option><?php endforeach;?></select><div class="sensor-date-field history-date-field"><label for="history_date_from">From</label><input id="history_date_from" type="date" name="date_from" value="<?=fgEscape($dateFrom)?>"></div><div class="sensor-date-field history-date-field"><label for="history_date_to">To</label><input id="history_date_to" type="date" name="date_to" value="<?=fgEscape($dateTo)?>"></div><button class="sensor-filter-button history-filter-button"><i class="bi bi-funnel-fill"></i> Apply Filters</button><?php if($search||$filter||$dateFrom||$dateTo):?><a class="sensor-clear-filter history-clear" href="history.php?tab=<?=fgEscape($tab)?>">Clear</a><?php endif;?></form>
<div class="table-container sensor-table-container history-table-wrap"><table class="admin-table sensor-history-table history-table history-table-<?=fgEscape($tab)?>"><thead><tr><?php if($tab==='incidents'):?><th>Date and Time</th><th>Incident</th><th>Location</th><th>Current Status</th><th>Updates</th><?php elseif($tab==='notifications'):?><th>Date and Time</th><th>Notification</th><th>Level</th><th>Residents</th><th>Delivered</th><th>Not Delivered</th><?php else:?><th>Date and Time</th><th>User</th><th>Activity</th><th>Entity</th><?php endif;?><th aria-label="Actions"></th></tr></thead><tbody>
<?php if(!$rows):?><tr><td class="history-empty" colspan="7"><i class="bi bi-inbox"></i><br>No history records found.</td></tr><?php endif;?>
<?php foreach($rows as $r):?><?php
if($tab==='incidents'){$details=['type'=>'incident','title'=>$r['incident_number'],'fields'=>['Report'=>$r['report_number'],'Location'=>$r['location_description'],'Priority'=>hLabel($r['priority']),'Current Status'=>hLabel($r['status']),'Created'=>date('M d, Y h:i A',strtotime($r['created_at'])),'Resolved'=>$r['resolved_at']?date('M d, Y h:i A',strtotime($r['resolved_at'])):'Not resolved'],'description'=>$r['resolution_summary']?:'No resolution summary.','timeline'=>$r['timeline']];}
elseif($tab==='notifications'){$details=['type'=>'notification','title'=>$r['title'],'fields'=>['Alert Level'=>hLabel($r['alert_level']),'Residents Targeted'=>(string)(int)$r['targeted'],'Successfully Delivered'=>(string)(int)$r['sent_count'],'Waiting for Delivery'=>(string)(int)$r['queued_count'],'Not Delivered'=>(int)$r['failed_count']+(int)$r['skipped_count'],'Created'=>date('M d, Y h:i A',strtotime($r['created_at']))],'description'=>$r['body']];}
else{$details=['type'=>'activity','title'=>hLabel($r['action']),'fields'=>['User'=>$r['actor_name']?:'System','Email'=>$r['actor_email']?:'Not available','Entity'=>hLabel($r['entity_type']),'Record'=>$r['entity_id']?'#'.$r['entity_id']:'General','Date and Time'=>date('M d, Y h:i:s A',strtotime($r['created_at']))],'before'=>hJson($r['before_json']),'after'=>hJson($r['after_json'])];}
$json=json_encode($details,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_UNESCAPED_UNICODE)?:'{}';?>
<tr class="sensor-reading-row history-record-row" tabindex="0" role="button" data-history-record="<?=fgEscape($json)?>">
<?php if($tab==='incidents'):?><td><div class="sensor-date-cell"><strong><?=fgEscape(date('M d, Y',strtotime($r['created_at'])))?></strong><span><?=fgEscape(date('h:i A',strtotime($r['created_at'])))?></span></div></td><td><div class="sensor-value-cell"><strong><?=fgEscape($r['incident_number'])?></strong><span><?=fgEscape($r['report_number'])?></span></div></td><td><?=fgEscape($r['location_description'])?></td><td><span class="history-badge <?=fgEscape($r['status'])?>"><?=fgEscape(hLabel($r['status']))?></span></td><td><?=number_format((int)$r['transition_count'])?> update<?=((int)$r['transition_count'])===1?'':'s'?></td>
<?php elseif($tab==='notifications'):?><td><div class="sensor-date-cell"><strong><?=fgEscape(date('M d, Y',strtotime($r['created_at'])))?></strong><span><?=fgEscape(date('h:i A',strtotime($r['created_at'])))?></span></div></td><td><div class="sensor-value-cell"><strong><?=fgEscape($r['title'])?></strong><span><?=fgEscape($r['body'])?></span></div></td><td><span class="history-badge <?=fgEscape($r['alert_level'])?>"><?=fgEscape(hLabel($r['alert_level']))?></span></td><td><?=number_format((int)$r['targeted'])?></td><td><div class="sensor-value-cell"><strong><?=number_format((int)$r['sent_count'])?></strong><span><?=((int)$r['targeted']>0)?round((int)$r['sent_count']*100/(int)$r['targeted']).'% delivery':'No recipients'?></span></div></td><td><?=number_format((int)$r['failed_count']+(int)$r['skipped_count'])?></td>
<?php else:?><td><div class="sensor-date-cell"><strong><?=fgEscape(date('M d, Y',strtotime($r['created_at'])))?></strong><span><?=fgEscape(date('h:i:s A',strtotime($r['created_at'])))?></span></div></td><td><div class="sensor-value-cell"><strong><?=fgEscape($r['actor_name']?:'System')?></strong><span><?=fgEscape($r['actor_email'])?></span></div></td><td><strong><?=fgEscape(hLabel($r['action']))?></strong></td><td><span class="history-badge"><?=fgEscape(hLabel($r['entity_type']))?></span><small><?=$r['entity_id']?'#'.(int)$r['entity_id']:'General'?></small></td><?php endif;?>
<td class="sensor-action-cell history-action-cell"><button type="button" class="view-sensor-button history-view-button" aria-label="View full details" title="View details"><i class="bi bi-eye-fill"></i></button></td></tr><?php endforeach;?></tbody></table></div>
<?php if($pages>1):?><footer class="sensor-pagination history-pagination"><span class="sensor-pagination-summary">Showing <?=number_format($offset+1)?> to <?=number_format(min($offset+$perPage,$total))?> of <?=number_format($total)?></span><div class="sensor-pagination-links history-page-links"><?php for($p=max(1,$page-2);$p<=min($pages,$page+2);$p++):?><a class="sensor-page-button <?=$p===$page?'active':''?>" href="<?=fgEscape(hUrl($tab,$p,$filters))?>"><?=$p?></a><?php endfor;?></div></footer><?php endif;?></section></main></div>
<dialog id="historyModal" class="history-modal"><header class="history-modal-header"><div><span class="section-label">Full Details</span><h2 id="historyModalTitle">History Record</h2></div><button type="button" class="history-modal-close" aria-label="Close"><i class="bi bi-x-lg"></i></button></header><div class="history-modal-body"><dl id="historyModalFields" class="history-modal-grid"></dl><div id="historyModalDescription" class="history-detail-block" hidden><span>Details</span><pre></pre></div><div id="historyModalBefore" class="history-detail-block" hidden>
    <span>Before</span><pre></pre></div><div id="historyModalAfter" class="history-detail-block" hidden><span>After</span><pre></pre></div><div id="historyModalTimeline" class="history-detail-block" hidden><span>Response Timeline</span><div class="history-timeline"></div></div></div></dialog>
<script src="../assets/js/admin.js"></script><script>(()=>{const m=document.getElementById('historyModal'),title=document.getElementById('historyModalTitle'),fields=document.getElementById('historyModalFields');if(!m)return;const block=(id,value)=>{const el=document.getElementById(id);el.hidden=!value;if(value)el.querySelector('pre').textContent=value};function open(row){let d;try{d=JSON.parse(row.dataset.historyRecord||'{}')}catch(e){return}title.textContent=d.title||'History Record';fields.innerHTML='';Object.entries(d.fields||{}).forEach(([k,v])=>{const x=document.createElement('div'),dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=k;dd.textContent=v||'—';x.append(dt,dd);fields.append(x)});block('historyModalDescription',d.description);block('historyModalBefore',d.before);block('historyModalAfter',d.after);const wrap=document.getElementById('historyModalTimeline'),list=wrap.querySelector('.history-timeline');list.innerHTML='';(d.timeline||[]).forEach(x=>{const item=document.createElement('div');item.className='history-timeline-item';const strong=document.createElement('strong'),span=document.createElement('span'),small=document.createElement('small');strong.textContent=(x.from_status?x.from_status.replaceAll('_',' ')+' → ':'')+(x.to_status||'updated').replaceAll('_',' ');span.textContent=(x.actor||'System')+' • '+(x.changed_at||'');small.textContent=x.notes||'No notes';item.append(strong,span,small);list.append(item)});wrap.hidden=!(d.timeline||[]).length;m.showModal()}document.querySelectorAll('.history-record-row').forEach(r=>{r.onclick=()=>open(r);r.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();open(r)}};r.querySelector('button')?.addEventListener('click',e=>{e.stopPropagation();open(r)})});m.querySelector('.history-modal-close').onclick=()=>m.close();m.onclick=e=>{if(e.target===m)m.close()}})();</script></body></html>
